import requests
from bs4 import BeautifulSoup
import time
import os

TOKEN = os.getenv("TELEGRAM_TOKEN")
CHAT_ID = os.getenv("CHAT_ID")
PRODUCT_URL = os.getenv("PRODUCT_URL")

def get_amazon_data(url):
    headers = {"User-Agent": "Mozilla/5.0"}
    r = requests.get(url, headers=headers)
    soup = BeautifulSoup(r.text, "html.parser")
    try:
        price = soup.select_one(".a-price .a-offscreen").text.strip()
    except:
        price = "Fiyat bulunamadı"
    try:
        availability = soup.select_one("#availability span").text.strip()
    except:
        availability = "Durum bilinmiyor"
    return price, availability

def send_telegram(message):
    url = f"https://api.telegram.org/bot{TOKEN}/sendMessage"
    data = {"chat_id": CHAT_ID, "text": message}
    requests.post(url, data=data)

last_status = None

while True:
    price, status = get_amazon_data(PRODUCT_URL)
    msg = f"🛒 Ürün: {PRODUCT_URL}\n💰 Fiyat: {price}\n📦 Durum: {status}"
    print(msg)

    if status != last_status:
        send_telegram(f"⚠️ Stok durumu değişti!\n{msg}")
        last_status = status

    time.sleep(3600)  # 1 saatda bir yoxlayır

import requests
from bs4 import BeautifulSoup

# 関西周辺の観測地点（好きに追加OK）
spots = {
    "大阪湾": "https://www.data.jma.go.jp/kaiyou/data/db/kaikyo/html/point/osaka.html",
    "神戸": "https://www.data.jma.go.jp/kaiyou/data/db/kaikyo/html/point/kobe.html",
    "和歌山": "https://www.data.jma.go.jp/kaiyou/data/db/kaikyo/html/point/wakayama.html",
    "白浜": "https://www.data.jma.go.jp/kaiyou/data/db/kaikyo/html/point/shirahama.html"
}

def get_sea_temp(url):
    try:
        res = requests.get(url)
        res.encoding = "utf-8"
        soup = BeautifulSoup(res.text, "html.parser")

        # テーブルから水温っぽい値を探す
        tables = soup.find_all("table")
        for table in tables:
            if "水温" in table.text:
                return table.text.strip().split("\n")[0:5]

        return "データ見つからん"
    except:
        return "取得エラー"

print("🌊 関西の海水温チェック\n")

for name, url in spots.items():
    print(f"【{name}】")
    result = get_sea_temp(url)

    if isinstance(result, list):
        for line in result:
            print(line)
    else:
        print(result)

    print("-" * 20)
